<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> const DEFAULT_MEMORY_FLUSH_PROMPT = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`</span></span>
